export const messageTranslations: Record<string, Record<string, string>> = Object.fromEntries(
  Object.entries(rows).map(([locale, row]) => {
    const values = row.split("|");
    if (values.length !== keys.length) throw new Error(`Invalid ${locale} message row: ${values.length}/${keys.length}`);
    return [locale, Object.fromEntries(keys.map((key, index) => [key, values[index]]))];
  }),
);
